// std-packages.ts: the text of the standard packages (spec 11.7), as published in std/. Generated by
// `npm run embed` in packages/crubal; a test refuses a copy that has drifted from the files. An adopter reads
// these into a dictionary before its own packages, as a publish does (11.4).

import { type Dictionary, emptyDictionary, readDefinitions } from "./defs.ts";

/** The standard packages' text, by name: core, units and party. */
export const STANDARD_PACKAGES: { readonly core: string; readonly units: string; readonly party: string } = {
  core: `// crubal.com/core: the core's own names (chapter 11.7). The envelope lines, origins and audiences are fixed
// by the specification; the facets below are the core facets every package may use as crubal:<name>.
package: core /2026-10-14
  owner: crubal.com
  label: CRUBAL core
  crubal: 2
  licence: CC-BY-4.0

facet: notables
  type: compound
  pick: any
  label: Notables
  describe: Facts true of this one record that no class asks for: signed, misprint, edition number. A key that recurs across enough records is proposed as a facet (chapter 9.5).
  facets:
    key$80
    value$

facet: count
  type: number
  label: Count
  describe: How many identical things a fungible part holds (chapter 5.6).

facet: items
  type: link
  pick: any
  ordered: yes
  label: Items
  describe: The records a hand-made list holds, in its order (chapter 12.2). A view shows the list with select: list.

facet: clonedFrom
  type: link
  label: Cloned from
  describe: The record this one was adopted from, when a whole record was made one's own (chapter 8.2).
`,
  units: `// crubal.com/units: the units table (chapter 1.4.3, 11.9). Units are reference records of the kind "measure";
// currencies are records of the kind "currency". Readers fold the spellings and convert within a dimension.
package: units /2026-10-15
  owner: crubal.com
  label: Units and currencies
  crubal: 2
  licence: CC-BY-4.0

kind: measure
  levels: measure
  base: Measure

kind: currency
  levels: currency
  base: Currency

facet: dimension
  type: choice
  values: time, length, mass, volume, area, temperature, data, count
  describe: The dimension a unit measures; units convert only within one. The list grows by versions of this package.

facet: factor
  type: number
  describe: How many of the dimension's base unit one of this unit is (s, m, kg, L, m2, K, B, each).

facet: offset
  type: number
  describe: For a unit whose zero isn't the base's (°C, °F): the base-unit amount at this unit's zero. An amount in base units is amount × factor + offset.

facet: spellings
  type: text
  pick: any
  describe: Other ways intake may write this unit; folded case-insensitively.

facet: uncefact
  type: text
  label: UN/CEFACT code
  describe: The unit's UN/CEFACT Recommendation 20 code, for borders that use it. Never a spelling.

facet: rounding
  type: number
  describe: On a dimension's base unit record: the decimal places a conversion keeps when the facet states none.

facet: places
  type: number
  describe: A currency's decimal places (ISO 4217 minor units).

facet: name
  type: text

class: Measure
  for: measure
  facets:
    !dimension
    !factor
    offset
    rounding
    spellings
    uncefact

class: Currency
  for: currency
  facets:
    !name
    !places
`,
  party: `// crubal.com/party: who acts. The three caller kinds, what any adopter needs of them, and the facets that
// access reads. Authentication stays in the host; roles and presets stay in the adopter's package.
package: party /2026-10-16
  owner: crubal.com
  label: Parties
  crubal: 2
  licence: CC-BY-4.0
  prefixes:
    schema: https://schema.org/

kind: person
  levels: person
  base: Person
  schema:
    person: schema:Person
kind: organization
  levels: organization
  base: Organization
  schema:
    organization: schema:Organization
kind: system
  levels: system
  base: System
  schema:
    system: schema:SoftwareApplication

// Any party
!name$200 =schema:name
image^ =schema:image
url$ =schema:url
email$ =schema:email
phone$ =schema:telephone
description$ =schema:description
roles&role*
memberOf&organization* =schema:memberOf

// People
givenName$ =schema:givenName
familyName$ =schema:familyName
locale$                                  // BCP 47: en-GB
timezone$                                // IANA: Europe/London
signedUp@ymdhm

// Organizations
legalName$ =schema:legalName
domain$ unique                           // the owner domain when the organization is one
taxId$ =schema:taxID
facet: address
  type: compound
  same-as: schema:address
  facets:
    street$ =schema:streetAddress
    locality$ =schema:addressLocality
    region$ =schema:addressRegion
    postalCode$ =schema:postalCode
    country$ =schema:addressCountry        // ISO 3166-1 alpha-2

// Systems
operator&organization                    // who runs it
systemKind{utility|partner|agent}
scheme{oauth2|apikey|basic|none}
scopes$*                                 // what was granted
requests$*                               // the menu items it asked for (14.9)
connection{connected|expired|revoked}
connectedAt@ymdhm
version$

class: Person
  for: person
  facets:
    !name
    givenName
    familyName
    image
    email
    phone
    locale
    timezone
    roles
    memberOf
    signedUp
class: Organization
  for: organization
  facets:
    !name
    legalName
    domain
    url
    email
    phone
    address
    image
    description
    taxId
class: System
  for: system
  facets:
    !name
    operator
    systemKind
    url
    scheme
    scopes
    requests
    connection
    connectedAt
    version
    roles

// Contact details and tax identity are for the owner's people, never for the public or other members.
rule: emailIsPrivate
  for: everywhere
  strength: must
  then: email shown to staff
rule: phoneIsPrivate
  for: everywhere
  strength: must
  then: phone shown to staff
rule: addressIsPrivate
  for: everywhere
  strength: must
  then: address shown to staff
rule: taxIdIsPrivate
  for: everywhere
  strength: must
  then: taxId shown to staff

// The host writes the connection through this form (host.md). The form is the party package's so every host
// writes the same record; the edge that grants what the system asked for is the adopter's (14.9).
contract: connect
  kind: form
  origin: observed
  needs:
    !name
    scheme
    scopes
    requests
    connection
    connectedAt

// A person keeps their own details. Who may run it is the adopter's edge (consume on their own record).
contract: profile
  kind: form
  origin: declared
  needs:
    !name
    givenName
    familyName
    image
    email
    phone
    locale
    timezone
`,
};

/** A dictionary holding the three standard packages' definitions, to read an adopter's packages onto. */
export function standardDefinitions(into: Dictionary = emptyDictionary()): Dictionary {
  for (const text of [STANDARD_PACKAGES.core, STANDARD_PACKAGES.units, STANDARD_PACKAGES.party]) readDefinitions(text, into);
  return into;
}
